const inputItems = $input.all();
const webhook = $('Process Webhook').first();
const webhookJson = webhook.json || {};

const documentId = String(inputItems[0].json.documentId || webhookJson.documentId || '');
const workspaceId = String(inputItems[0].json.workspaceId || webhookJson.workspaceId || '');

let documentName = String(inputItems[0].json.documentName || webhookJson.fileName || webhookJson.documentName || '');
if (!documentName) {
  documentName = documentId;
}

const CHUNK_SIZE = 1000;
const CHUNK_OVERLAP = 150;

function httpStatus(res) {
  return res && res.statusCode !== undefined ? res.statusCode : res && res.status;
}

function pageNumberForPosition(pos, ranges) {
  for (let i = 0; i < ranges.length; i++) {
    if (pos >= ranges[i].start && pos < ranges[i].end) {
      return ranges[i].page;
    }
  }
  return ranges.length ? ranges[ranges.length - 1].page : 0;
}

function splitIntoPages(text) {
  const trimmed = String(text || '');
  const segments = [];

  if (trimmed.indexOf('\f') !== -1) {
    const parts = trimmed.split('\f');
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i].trim();
      if (part.length > 0) {
        segments.push({ page: i + 1, text: part });
      }
    }
    if (segments.length > 1) {
      return segments;
    }
    segments.length = 0;
  }

  const markerPattern = /(?:^|\r?\n)[ \t]*(?:-{3,}[ \t]*)?(?:page[ \t]*(\d+)|\[page[ \t]*(\d+)\]|\[(\d+)\])[ \t]*(?:-{3,})?[ \t]*(?=\r?\n|$)/gi;
  let match;
  let cursor = 0;
  let pageCounter = 0;
  while ((match = markerPattern.exec(trimmed)) !== null) {
    const before = trimmed.slice(cursor, match.index).trim();
    if (before.length > 0) {
      segments.push({ page: pageCounter + 1, text: before });
    }
    const markerPage = match[1] || match[2] || match[3];
    pageCounter = markerPage ? parseInt(markerPage, 10) : pageCounter + 1;
    cursor = match.index;
  }
  if (segments.length > 0) {
    const rest = trimmed.slice(cursor).trim();
    if (rest.length > 0) {
      segments.push({ page: pageCounter + 1, text: rest });
    }
    return segments;
  }

  return [{ page: 0, text: trimmed }];
}

function buildChunks(pageSegments) {
  const chunks = [];
  if (!pageSegments.length) {
    return chunks;
  }

  const combined = [];
  for (let i = 0; i < pageSegments.length; i++) {
    if (i > 0) {
      combined.push({ text: '\n\n', page: pageSegments[i].page });
    }
    combined.push({ text: pageSegments[i].text, page: pageSegments[i].page });
  }

  const ranges = [];
  let cursor = 0;
  for (const seg of combined) {
    ranges.push({ page: seg.page, start: cursor, end: cursor + seg.text.length });
    cursor += seg.text.length;
  }
  const fullText = combined.map((s) => s.text).join('');
  const total = fullText.length;

  let start = 0;
  while (start < total) {
    let end = Math.min(start + CHUNK_SIZE, total);
    if (end < total) {
      const searchFrom = Math.min(start + Math.floor(CHUNK_SIZE * 0.8), total);
      const period = fullText.lastIndexOf('. ', end);
      const newline = fullText.lastIndexOf('\n', end);
      const space = fullText.lastIndexOf(' ', end);
      const breakAt = Math.max(period, newline, space);
      if (breakAt > searchFrom) {
        end = breakAt + 1;
      }
    }
    const chunkText = fullText.slice(start, end).trim();
    if (chunkText.length > 0) {
      chunks.push({ text: chunkText, page: pageNumberForPosition(start, ranges) });
    }
    if (end >= total) {
      break;
    }
    const next = Math.max(end - CHUNK_OVERLAP, start + 1);
    if (next >= end) {
      break;
    }
    start = next;
  }
  return chunks;
}

function uuid() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

async function embedText(text) {
  const res = await $http.request({
    method: 'POST',
    url: `${$env.EMBEDDING_BASE_URL}/embeddings`,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${$env.EMBEDDING_API_KEY}`,
    },
    body: {
      model: $env.EMBEDDING_MODEL,
      input: text,
    },
  });
  if (httpStatus(res) >= 400) {
    throw new Error(`Embedding request failed (${httpStatus(res)}): ${JSON.stringify(res.body || {})}`);
  }
  const data = res.body && res.body.data;
  if (!data || !data.length || !Array.isArray(data[0].embedding) || !data[0].embedding.length) {
    throw new Error('Embedding response did not contain a valid vector');
  }
  return data[0].embedding;
}

async function callLlm(messages) {
  const res = await $http.request({
    method: 'POST',
    url: `${$env.LLM_BASE_URL}/chat/completions`,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${$env.LLM_API_KEY}`,
    },
    body: {
      model: $env.LLM_MODEL,
      temperature: 0,
      max_tokens: 1600,
      messages,
    },
  });
  if (httpStatus(res) >= 400) {
    throw new Error(`LLM request failed (${httpStatus(res)}): ${JSON.stringify(res.body || {})}`);
  }
  const choice = res.body && res.body.choices && res.body.choices[0];
  if (!choice || !choice.message || typeof choice.message.content !== 'string') {
    throw new Error('LLM response did not contain message content');
  }
  return choice.message.content;
}

function parseSummary(raw) {
  let text = String(raw || '').trim();
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/g, '').trim();
  let obj = null;
  try {
    obj = JSON.parse(text);
  } catch (e) {
    obj = null;
  }
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
    return null;
  }
  return {
    shortSummary: typeof obj.shortSummary === 'string' ? obj.shortSummary : '',
    detailedSummary: typeof obj.detailedSummary === 'string' ? obj.detailedSummary : '',
    keyPoints: Array.isArray(obj.keyPoints) ? obj.keyPoints.map((v) => String(v)) : [],
    importantTopics: Array.isArray(obj.importantTopics) ? obj.importantTopics.map((v) => String(v)) : [],
    importantDefinitions: Array.isArray(obj.importantDefinitions)
      ? obj.importantDefinitions.map((d) => {
          if (d && typeof d === 'object' && !Array.isArray(d)) {
            return `${String(d.term || '')}: ${String(d.definition || '')}`.trim();
          }
          return String(d);
        })
      : [],
  };
}

let error = null;
let summary = null;
let pages = 0;
let chunkCount = 0;

const extractedText = String(inputItems[0].json.data || '');
if (!extractedText.trim()) {
  error = 'No file binary was attached to the webhook, so no text could be extracted. Configure the backend to send the PDF binary to this webhook, or mount a shared volume so the workflow can read the filePath.';
}

if (!error) {
  try {
    const pageSegments = splitIntoPages(extractedText);
    pages = pageSegments.reduce((max, seg) => (seg.page > max ? seg.page : max), 0);
    if (pages === 0 && pageSegments.length > 0) {
      pages = 1;
    }

    const chunks = buildChunks(pageSegments);
    if (!chunks.length) {
      throw new Error('No text could be extracted from the uploaded document');
    }
    chunkCount = chunks.length;

    const points = [];
    for (const chunk of chunks) {
      const vector = await embedText(chunk.text);
      points.push({
        id: uuid(),
        vector,
        payload: {
          workspace_id: workspaceId,
          document_id: documentId,
          document_name: documentName,
          page: chunk.page || 0,
          text: chunk.text,
        },
      });
    }

    const upsertRes = await $http.request({
      method: 'POST',
      url: `${$env.QDRANT_URL}/collections/careeros_pdf_chunks/points?wait=true`,
      headers: { 'Content-Type': 'application/json' },
      body: { points },
    });
    if (httpStatus(upsertRes) >= 400) {
      throw new Error(`Qdrant upsert failed (${httpStatus(upsertRes)}): ${JSON.stringify(upsertRes.body || {})}`);
    }

    const fullDocText = pageSegments.map((seg) => seg.text).join('\n\n');
    const summaryPrompt =
      'Analyze the uploaded PDF document. Generate: 1) shortSummary 2) detailedSummary 3) keyPoints (array of strings) 4) importantTopics (array of strings) 5) importantDefinitions (array of {term, definition}). Return ONLY valid JSON matching: {"shortSummary":"","detailedSummary":"","keyPoints":[],"importantTopics":[],"importantDefinitions":[{"term":"","definition":""}]}\n\nDocument text:\n' +
      fullDocText.slice(0, 8000);

    const llmOutput = await callLlm([
      { role: 'system', content: 'You are a document analysis assistant. Always respond with valid JSON and nothing else.' },
      { role: 'user', content: summaryPrompt },
    ]);

    summary = parseSummary(llmOutput);
    if (!summary) {
      summary = {
        shortSummary: '',
        detailedSummary: String(llmOutput || '').slice(0, 2000),
        keyPoints: [],
        importantTopics: [],
        importantDefinitions: [],
      };
    }
  } catch (e) {
    error = e && e.message ? String(e.message) : 'Unknown processing error';
  }
}

const result = {
  documentId,
  workspaceId,
  pages,
  chunkCount,
  shortSummary: summary ? summary.shortSummary : '',
  detailedSummary: summary ? summary.detailedSummary : '',
  keyPoints: summary ? summary.keyPoints : [],
  importantTopics: summary ? summary.importantTopics : [],
  importantDefinitions: summary ? summary.importantDefinitions : [],
};
if (error) {
  result.error = error;
}
return [{ json: result }];

const input = $input.first().json;
const documentId = String(input.documentId || '');

const markdownParts = [];
if (input.shortSummary) markdownParts.push('**Summary**\n\n' + input.shortSummary);
if (input.detailedSummary) markdownParts.push('**Details**\n\n' + input.detailedSummary);
if (Array.isArray(input.keyPoints) && input.keyPoints.length) {
  markdownParts.push('**Key Points**\n' + input.keyPoints.map((k) => '- ' + k).join('\n'));
}
if (Array.isArray(input.importantTopics) && input.importantTopics.length) {
  markdownParts.push('**Important Topics**\n' + input.importantTopics.map((t) => '- ' + t).join('\n'));
}
if (Array.isArray(input.importantDefinitions) && input.importantDefinitions.length) {
  markdownParts.push('**Definitions**\n' + input.importantDefinitions.map((d) => '- ' + d).join('\n'));
}

const body = {
  documentId,
  status: input.error ? 'FAILED' : 'READY',
  summary: markdownParts.join('\n\n'),
  chunkCount: typeof input.chunkCount === 'number' ? input.chunkCount : 0,
  source: 'n8n',
};
if (input.error) {
  body.error = String(input.error);
}

const url = `${$env.BACKEND_URL}/api/v1/pdf-assistant/internal/result`;
let callbackError = null;

try {
  const res = await $http.request({
    method: 'POST',
    url,
    headers: {
      'Content-Type': 'application/json',
      'X-Internal-Key': $env.PDF_ASSISTANT_INTERNAL_KEY,
    },
    body,
  });
  const status = res.statusCode !== undefined ? res.statusCode : res.status;
  if (status >= 400) {
    callbackError = `Backend result callback returned status ${status}: ${JSON.stringify(res.body || {})}`;
  }
} catch (e) {
  callbackError = e && e.message ? `Backend result callback failed: ${e.message}` : 'Backend result callback failed';
}

return [{ json: { success: !callbackError, callbackError, documentId } }];
